# Rebuilds web/study-problems.js and re-derives every numeric answer key independently.
#   python build-study.py   (run from the repository root)
# The questions are original. They follow the sections of my Chemistry Olympiad guide and the
# kinds of questions in the club's practice sets, with new numbers and wording; the real past
# exams belong to the ACS and are linked from the page instead of copied.
import json, math, re
P=[]; V={}
def add(id,section,topic,title,statement,choices,answer,hint,solution,value=None):
    assert len(choices)==4 and len(set(choices))==4 and choices.count(answer)==1,(id,answer,choices)
    P.append(dict(id=id,subject=section,topic=topic,title=title,statement=statement,choices=choices,answer=choices.index(answer),hint=hint,solution=solution))
    if value is not None: V[id]=value
R=8.314
S='Stoichiometry'; M='States of matter'; T='Thermodynamics'; K='Kinetics'; E='Equilibrium and acids'; O='Bonding, redox and organic'
# ---------------- Stoichiometry ----------------
add('st-01',S,'Isotopes','Two isotopes of copper','Copper has two stable isotopes, ⁶³Cu (62.93 u) and ⁶⁵Cu (64.93 u), and an average atomic mass of 63.55 u. What percent of copper atoms are ⁶³Cu?',['31.0%','50.0%','69.0%','75.0%'],'69.0%','Let x be the fraction of the lighter isotope: 62.93x + 64.93(1 − x) = 63.55.','62.93x + 64.93 − 64.93x = 63.55, so 2.00x = 1.38 and x = 0.690. 69.0% is ⁶³Cu. Answer: C.',100*(64.93-63.55)/(64.93-62.93))
add('st-02',S,'Limiting reactant','Limiting reactant','Aluminum reacts with chlorine: 2 Al + 3 Cl₂ → 2 AlCl₃. If 5.40 g of Al (26.98 g/mol) and 10.65 g of Cl₂ (70.90 g/mol) react completely, what mass of AlCl₃ (133.33 g/mol) forms?',['8.90 g','13.4 g','20.0 g','26.7 g'],'13.4 g','Convert both to moles, then divide each by its coefficient to find which runs out first.','Al: 5.40/26.98 = 0.200 mol. Cl₂: 10.65/70.90 = 0.1502 mol. Per coefficient: 0.200/2 = 0.100 and 0.1502/3 = 0.0501, so Cl₂ is limiting. AlCl₃ formed = 0.1502 × (2/3) = 0.1001 mol, and 0.1001 × 133.33 = 13.4 g. Answer: B.',min(5.40/26.98/2,10.65/70.90/3)*2*133.33)
add('st-03',S,'Molarity','Dilution','What volume of 6.00 M HCl is needed to prepare 250. mL of 0.150 M HCl?',['3.13 mL','6.25 mL','12.5 mL','25.0 mL'],'6.25 mL','Moles of solute do not change on dilution: M₁V₁ = M₂V₂.','V₁ = (0.150)(250.)/6.00 = 6.25 mL. Answer: B.',0.150*250/6.00)
add('st-04',S,'Unit conversion','Counting atoms','How many hydrogen atoms are in 3.60 g of water (18.02 g/mol)?',['1.20 × 10²³','2.41 × 10²³','3.61 × 10²³','1.20 × 10²⁴'],'2.41 × 10²³','Grams → moles of H₂O → molecules → atoms. Each molecule has two H atoms.','3.60/18.02 = 0.1998 mol H₂O. Molecules: 0.1998 × 6.022×10²³ = 1.203×10²³. H atoms: twice that, 2.41×10²³. Answer: B.',3.60/18.02*6.022e23*2)
add('st-05',S,'Mass percent','Empirical formula','A compound is 40.0% C, 6.71% H and 53.3% O by mass. What is its empirical formula?',['CHO','CH₂O','C₂H₄O','CH₄O'],'CH₂O','Assume 100 g, convert each mass to moles, then divide by the smallest.','C: 40.0/12.01 = 3.33. H: 6.71/1.008 = 6.66. O: 53.3/16.00 = 3.33. Dividing by 3.33 gives 1 : 2 : 1, so CH₂O. Answer: B.')
add('st-06',S,'Identify the element','Unknown carbonate','Heating 2.00 g of a metal carbonate, MCO₃, drives off all its carbon as 0.880 g of CO₂ (44.01 g/mol). Which metal is M?',['Mg','Ca','Sr','Ba'],'Ca','Moles of CO₂ equal moles of MCO₃. Then find the molar mass of MCO₃ and subtract CO₃.','0.880/44.01 = 0.0200 mol CO₂ = 0.0200 mol MCO₃. Molar mass = 2.00/0.0200 = 100.0 g/mol. Subtract CO₃ (60.01): M ≈ 40.0 g/mol, calcium. Answer: B.')
assert abs(2.00/(0.880/44.01)-60.01-40.08)<0.2
# ---------------- States of matter ----------------
add('sm-01',M,'Gas laws','Identify the gas','A gas has a density of 1.96 g/L at 0 °C and 1.00 atm. Which gas is it? (R = 0.08206 L·atm/mol·K)',['N₂','O₂','CO₂','SO₂'],'CO₂','Molar mass = dRT/P.','M = (1.96)(0.08206)(273.15)/1.00 = 43.9 g/mol, which matches CO₂ (44.0 g/mol). Answer: C.')
assert abs(1.96*0.08206*273.15-44.01)<0.3
add('sm-02',M,'Partial pressure','Parts per million','Air in a lab contains 250 ppm of CO by volume at a total pressure of 760. mmHg. What is the partial pressure of CO?',['0.019 mmHg','0.19 mmHg','1.9 mmHg','19 mmHg'],'0.19 mmHg','For gases, volume fraction equals mole fraction. 250 ppm = 250 × 10⁻⁶.','P(CO) = (250×10⁻⁶)(760.) = 0.19 mmHg. Answer: B.',250e-6*760)
add('sm-03',M,'Effusion','Half the rate','At the same temperature, which gas effuses about half as fast as methane, CH₄?',['He','O₂','SO₂','Xe'],'SO₂','Rate is proportional to 1/√M. Half the rate means four times the molar mass.','CH₄ is 16.0 g/mol, so the gas must be about 64 g/mol. SO₂ is 64.1 g/mol. Answer: C.')
assert abs(math.sqrt(16.04/64.07)-0.5)<0.01
add('sm-04',M,'Unit cells','Counting atoms in a cell','In a cubic unit cell, X atoms sit at the corners and Y atoms at the centers of the faces. What is the formula of the compound?',['XY','XY₂','XY₃','X₃Y'],'XY₃','A corner atom is shared by 8 cells; a face atom by 2.','X: 8 × 1/8 = 1. Y: 6 × 1/2 = 3. The formula is XY₃. Answer: C.')
add('sm-05',M,'Unit cells','Density of copper','Copper crystallizes in a face-centered cubic cell with an edge length of 361.5 pm. What is its density? (63.55 g/mol)',['2.23 g/cm³','4.47 g/cm³','8.93 g/cm³','17.9 g/cm³'],'8.93 g/cm³','ρ = Z·M/(N_A·a³), with Z = 4 for FCC. Convert pm to cm first.','a = 3.615×10⁻⁸ cm, so a³ = 4.724×10⁻²³ cm³. ρ = (4)(63.55)/[(6.022×10²³)(4.724×10⁻²³)] = 8.93 g/cm³. Answer: C.',4*63.55/(6.022e23*(361.5e-10)**3))
add('sm-06',M,'Vapor pressure','Weakest attractions','Which compound has the highest vapor pressure at 25 °C?',['CH₃CH₂CH₂CH₃','CH₃CH₂CH₂OH','CH₃COCH₃','HOCH₂CH₂OH'],'CH₃CH₂CH₂CH₃','Weaker intermolecular forces mean more molecules escape into the vapor.','Butane has only dispersion forces. Acetone adds dipole–dipole attractions, and the two alcohols hydrogen-bond (the diol most of all). Butane is the most volatile; it is a gas at 25 °C. Answer: A.')
add('sm-07',M,'Phase changes','Ice at its melting point','Ice melts reversibly at 0 °C and 1 atm. Which set of signs is correct for the process?',['ΔH > 0, ΔS > 0, ΔG = 0','ΔH > 0, ΔS > 0, ΔG < 0','ΔH < 0, ΔS > 0, ΔG < 0','ΔH > 0, ΔS < 0, ΔG = 0'],'ΔH > 0, ΔS > 0, ΔG = 0','At the normal melting point the two phases are in equilibrium.','Melting absorbs heat (ΔH > 0) and increases disorder (ΔS > 0). At exactly the melting point solid and liquid coexist, so ΔG = 0, which is why T = ΔH/ΔS there. Answer: A.')
add('sm-08',M,'Solutions','Freezing point','What is the freezing point of a 0.100 m aqueous CaCl₂ solution, assuming complete dissociation? (Kf = 1.86 °C/m)',['−0.186 °C','−0.372 °C','−0.558 °C','−0.744 °C'],'−0.558 °C','ΔTf = i·Kf·m. Count the ions per formula unit.','CaCl₂ gives 3 ions, so ΔTf = (3)(1.86)(0.100) = 0.558 °C and the solution freezes at −0.558 °C. Answer: C.',-3*1.86*0.100)
# ---------------- Thermodynamics ----------------
add('th-01',T,'Hess’s law','Heat of combustion','Standard enthalpies of formation (kJ/mol): CO₂(g) −393.5, H₂O(l) −285.8, C₂H₅OH(l) −277.7. What is ΔH° for C₂H₅OH(l) + 3 O₂(g) → 2 CO₂(g) + 3 H₂O(l)?',['−1366.7 kJ','−957.0 kJ','−401.6 kJ','+1366.7 kJ'],'−1366.7 kJ','ΔH° = Σ ΔHf(products) − Σ ΔHf(reactants). O₂ is an element in its standard state.','Products: 2(−393.5) + 3(−285.8) = −1644.4 kJ. Reactants: −277.7 + 0. ΔH° = −1644.4 − (−277.7) = −1366.7 kJ. Answer: A.',2*-393.5+3*-285.8+277.7)
t2=22.00+0.0500*56.0e3/(100.0*4.184)
add('th-02',T,'Calorimetry','Mixing acid and base','50.0 mL of 1.00 M HCl and 50.0 mL of 1.00 M NaOH, both at 22.00 °C, are mixed in a coffee-cup calorimeter. ΔH for neutralization is −56.0 kJ per mole of water formed. Treat the mixture as 100.0 g of water (4.184 J/g·°C). What is the final temperature?',['25.35 °C','28.69 °C','33.38 °C','35.38 °C'],'28.69 °C','Heat released by the reaction = heat gained by the solution, q = mcΔT.','Moles of water formed: 0.0500. Heat released: 0.0500 × 56.0 = 2.80 kJ = 2800 J. ΔT = 2800/[(100.0)(4.184)] = 6.69 °C. Final temperature = 22.00 + 6.69 = 28.69 °C. Answer: B.',t2)
add('th-03',T,'Enthalpy of formation','Which reaction defines ΔHf?','For which reaction is ΔH°rxn equal to the standard enthalpy of formation of MgCO₃(s)?',['MgO(s) + CO₂(g) → MgCO₃(s)','Mg(s) + C(graphite) + 3/2 O₂(g) → MgCO₃(s)','2 Mg(s) + 2 C(graphite) + 3 O₂(g) → 2 MgCO₃(s)','Mg(s) + C(graphite) + 3 O(g) → MgCO₃(s)'],'Mg(s) + C(graphite) + 3/2 O₂(g) → MgCO₃(s)','A formation reaction makes exactly one mole of the compound from its elements in their standard states.','Only the second equation forms 1 mol of MgCO₃ from elements in their standard states (solid Mg, graphite, O₂ gas). The first starts from compounds, the third makes 2 mol, and the fourth uses O atoms. Answer: B.')
add('th-04',T,'Calorimetry','Bomb calorimeter','A reaction is run in a sealed, rigid bomb calorimeter. The heat measured is equal to which quantity for the reaction?',['ΔH','ΔE (internal energy)','ΔG','The work done'],'ΔE (internal energy)','What can a rigid container not do?','At constant volume no pressure–volume work is done, so ΔE = q_v. ΔH equals the heat only at constant pressure; the two differ by Δ(PV), which matters when moles of gas change. Answer: B.')
t5=math.exp(-(31.0e3/R)*(1/323.15-1/353.15))
add('th-05',T,'Clausius–Clapeyron','Vapor pressure below the boiling point','A liquid has a normal boiling point of 80.0 °C and ΔH°vap = 31.0 kJ/mol. What is its vapor pressure at 50.0 °C? (R = 8.314 J/mol·K)',['0.188 atm','0.375 atm','0.620 atm','0.850 atm'],'0.375 atm','At the normal boiling point the vapor pressure is 1.00 atm. Use ln(P₂/P₁) = −(ΔH/R)(1/T₂ − 1/T₁) with kelvins.','ln(P/1.00) = −(31,000/8.314)(1/323.15 − 1/353.15) = −(3729)(2.629×10⁻⁴) = −0.980. P = e^(−0.980) = 0.375 atm. Answer: B.',t5)
add('th-06',T,'Free energy and K','Reading K against temperature','A reaction has K = 15 at 298 K, and K increases as the temperature rises. Which conclusions are valid? I. ΔG° < 0 at 298 K. II. ΔH° > 0.',['I only','II only','Both I and II','Neither I nor II'],'Both I and II','ΔG° = −RT ln K, and van ’t Hoff: K rises with T for an endothermic reaction.','K > 1 means ln K > 0, so ΔG° = −RT ln K is negative: I is true. K growing with temperature means heat acts like a reactant, so the reaction is endothermic: II is true. Answer: C.')
add('th-07',T,'Clausius–Clapeyron','Slope of ln P against 1/T','A plot of ln(vapor pressure) against 1/T for a liquid is a straight line with slope −5200 K. What is ΔH°vap? (R = 8.314 J/mol·K)',['5.20 kJ/mol','26.0 kJ/mol','43.2 kJ/mol','62.5 kJ/mol'],'43.2 kJ/mol','The slope of ln P vs 1/T is −ΔH/R.','ΔH = −(slope)(R) = (5200)(8.314) = 43,200 J/mol = 43.2 kJ/mol. Answer: C.',5200*R/1000)
add('th-08',T,'Gibbs free energy','When does it become spontaneous?','A reaction has ΔH° = +40.0 kJ and ΔS° = +125 J/K. Above what temperature is it spontaneous under standard conditions?',['0.320 K','3.13 K','320 K','It is spontaneous at all temperatures'],'320 K','Set ΔG° = ΔH° − TΔS° = 0, and make the units match.','T = ΔH°/ΔS° = 40,000 J / 125 J/K = 320 K. Above 320 K the −TΔS° term outweighs ΔH° and ΔG° < 0. Answer: C.',40.0e3/125)
add('th-09',T,'Bond enthalpies','Estimating ΔH from bonds','Bond dissociation enthalpies (kJ/mol): H–H 436, Cl–Cl 243, H–Cl 431. Estimate ΔH for H₂(g) + Cl₂(g) → 2 HCl(g).',['−248 kJ','−183 kJ','+183 kJ','+248 kJ'],'−183 kJ','ΔH ≈ (bonds broken) − (bonds formed).','Broken: 436 + 243 = 679 kJ. Formed: 2 × 431 = 862 kJ. ΔH ≈ 679 − 862 = −183 kJ. Answer: B.',436+243-2*431)
# ---------------- Kinetics ----------------
add('ki-01',K,'Half-life','First-order decay','A first-order reaction has a half-life of 20 minutes. What percent of the reactant remains after 60 minutes?',['6.25%','12.5%','25%','33%'],'12.5%','For first order, every half-life cuts the amount in half regardless of how much is left.','60 minutes is three half-lives, so (1/2)³ = 1/8 = 12.5% remains. Answer: B.',100*0.5**3)
add('ki-02',K,'Rate laws','Units of k','For A + B → products, doubling [A] quadruples the rate and doubling [B] doubles the rate. What are the units of the rate constant?',['s⁻¹','M⁻¹·s⁻¹','M⁻²·s⁻¹','M·s⁻¹'],'M⁻²·s⁻¹','Find each order first. The units of k are M^(1−n)·s⁻¹ for overall order n.','Rate = k[A]²[B], third order overall. k = rate/([A]²[B]) has units (M/s)/M³ = M⁻²·s⁻¹. Answer: C.')
add('ki-03',K,'Half-life','From half-life to k','A first-order reaction has a half-life of 34.7 s. What is its rate constant?',['0.0100 s⁻¹','0.0200 s⁻¹','0.0288 s⁻¹','24.0 s⁻¹'],'0.0200 s⁻¹','For first order, t½ = ln 2 / k.','k = 0.693/34.7 s = 0.0200 s⁻¹. Answer: B.',math.log(2)/34.7)
add('ki-04',K,'Activation energy','Doubling with ten degrees','A rate constant doubles when the temperature rises from 300. K to 310. K. What is the activation energy? (R = 8.314 J/mol·K)',['5.36 kJ/mol','26.8 kJ/mol','53.6 kJ/mol','107 kJ/mol'],'53.6 kJ/mol','ln(k₂/k₁) = (Ea/R)(1/T₁ − 1/T₂).','ln 2 = (Ea/8.314)(1/300. − 1/310.) = (Ea/8.314)(1.075×10⁻⁴). Ea = (0.693)(8.314)/(1.075×10⁻⁴) = 53,600 J/mol = 53.6 kJ/mol. Answer: C.',math.log(2)*R/(1/300-1/310)/1000)
add('ki-05',K,'Mechanisms','Catalyst or intermediate?','Ozone is destroyed by the mechanism: Step 1: O₃ + Cl → ClO + O₂. Step 2: ClO + O → Cl + O₂. Which description is correct?',['Cl is a catalyst and ClO is an intermediate','Cl is an intermediate and ClO is a catalyst','Both are catalysts','Both are intermediates'],'Cl is a catalyst and ClO is an intermediate','A catalyst is used up and then regenerated; an intermediate is made and then used up.','Cl is consumed in step 1 and regenerated in step 2, so it is a catalyst. ClO is produced in step 1 and consumed in step 2, so it is an intermediate. Neither appears in the overall reaction, O₃ + O → 2 O₂. Answer: A.')
add('ki-06',K,'Rate constants','What changes k?','Which change alters the value of the rate constant, k, for a gas-phase reaction?',['Increasing a reactant concentration','Adding an inert gas at constant volume','Raising the temperature','Doubling the container volume'],'Raising the temperature','Think of the Arrhenius equation: what does k depend on?','k = A·e^(−Ea/RT) depends only on temperature and on the pathway (a catalyst changes Ea). Concentration, volume and inert gases change the rate at most, never k. Answer: C.')
add('ki-07',K,'Integrated rate laws','Second-order decay','A second-order reaction has k = 0.500 M⁻¹·s⁻¹ and an initial concentration of 0.100 M. What is the concentration after 20.0 s?',['0.0250 M','0.0368 M','0.0500 M','0.0900 M'],'0.0500 M','For second order, 1/[A] = kt + 1/[A]₀.','1/[A] = (0.500)(20.0) + 1/0.100 = 10.0 + 10.0 = 20.0 M⁻¹, so [A] = 0.0500 M. Answer: C.',1/(0.500*20.0+1/0.100))
# ---------------- Equilibrium and acids ----------------
x=(-0.2+math.sqrt(0.04+3.2))/8
add('eq-01',E,'Equilibrium','Dissociation of N₂O₄','For N₂O₄(g) ⇌ 2 NO₂(g), Kc = 0.20 at a certain temperature. A flask initially contains only 1.00 M N₂O₄. What is [NO₂] at equilibrium?',['0.20 M','0.40 M','0.45 M','0.80 M'],'0.40 M','Let x be the decrease in [N₂O₄]; then [NO₂] = 2x. Solve the quadratic.','(2x)²/(1.00 − x) = 0.20 gives 4x² + 0.20x − 0.20 = 0, so x = (−0.20 + √3.24)/8 = 0.200. [NO₂] = 2x = 0.40 M. Check: 0.16/0.80 = 0.20. Answer: B.',2*x)
add('eq-02',E,'Le Châtelier','Making more ammonia','N₂(g) + 3 H₂(g) ⇌ 2 NH₃(g) is exothermic. Which change increases the equilibrium amount of NH₃?',['Raising the temperature','Decreasing the container volume','Adding a catalyst','Removing some H₂'],'Decreasing the container volume','Compare moles of gas on each side, and treat heat as a product.','A smaller volume raises the pressure, and the system shifts toward fewer moles of gas (4 → 2), making more NH₃. Heating shifts an exothermic reaction left, a catalyst does not move the equilibrium, and removing H₂ shifts it left. Answer: B.')
add('eq-03',E,'Acids and bases','Weak acid pH','What is the pH of 0.10 M acetic acid? (Ka = 1.8 × 10⁻⁵)',['1.00','2.87','4.74','5.74'],'2.87','[H⁺] ≈ √(Ka·C) when dissociation is small.','[H⁺] = √(1.8×10⁻⁵ × 0.10) = 1.34×10⁻³ M, so pH = 2.87. (Only 1.3% dissociates, so the approximation holds.) Answer: B.',-math.log10(math.sqrt(1.8e-5*0.10)))
add('eq-04',E,'Buffers','Half-neutralized','0.050 mol of NaOH is added to 1.0 L of 0.10 M acetic acid (Ka = 1.8 × 10⁻⁵). What is the pH? Assume no volume change.',['2.87','4.44','4.74','7.00'],'4.74','After the reaction, compare moles of acid left with moles of conjugate base formed.','NaOH converts 0.050 mol of acid to acetate, leaving 0.050 mol of each. With [HA] = [A⁻], pH = pKa = −log(1.8×10⁻⁵) = 4.74. Answer: C.',-math.log10(1.8e-5))
add('eq-05',E,'Solubility','Common ion effect','Ksp of AgCl is 1.8 × 10⁻¹⁰. What is its molar solubility in 0.10 M NaCl?',['1.3 × 10⁻⁵ M','1.8 × 10⁻⁹ M','1.8 × 10⁻¹⁰ M','1.8 × 10⁻¹¹ M'],'1.8 × 10⁻⁹ M','[Cl⁻] is essentially fixed at 0.10 M by the NaCl.','Ksp = [Ag⁺][Cl⁻] = s(0.10), so s = 1.8×10⁻¹⁰/0.10 = 1.8×10⁻⁹ M. (In pure water it would be 1.3×10⁻⁵ M.) Answer: B.',1.8e-10/0.10)
# ---------------- Bonding, redox and organic ----------------
add('bo-01',O,'Electrochemistry','Cell free energy','For Zn(s) + Cu²⁺(aq) → Zn²⁺(aq) + Cu(s), E°(Cu²⁺/Cu) = +0.34 V and E°(Zn²⁺/Zn) = −0.76 V. What is ΔG°? (F = 96,485 C/mol)',['−106 kJ','−212 kJ','−318 kJ','+212 kJ'],'−212 kJ','E°cell = E°cathode − E°anode, then ΔG° = −nFE°.','E°cell = 0.34 − (−0.76) = 1.10 V, and n = 2. ΔG° = −(2)(96,485)(1.10) = −212,000 J = −212 kJ. Answer: B.',-2*96485*1.10/1000)
add('bo-02',O,'Bonding','Molecular polarity','Which molecule has a nonzero dipole moment?',['CO₂','BF₃','SF₄','XeF₄'],'SF₄','Find each shape with VSEPR and ask whether the bond dipoles cancel.','CO₂ is linear, BF₃ trigonal planar and XeF₄ square planar, so their bond dipoles cancel. SF₄ has five electron domains with one lone pair (see-saw), which does not cancel. Answer: C.')
add('bo-03',O,'Organic','Alcohol isomers','How many constitutional isomers with the formula C₄H₁₀O are alcohols?',['2','3','4','5'],'4','Draw the two butane skeletons and place the OH on each distinct carbon.','Straight chain: 1-butanol and 2-butanol. Branched chain: 2-methyl-1-propanol and 2-methyl-2-propanol. That is 4 (the other C₄H₁₀O isomers are ethers). Answer: C.')
# ---------------- numeric re-check: the keyed choice must be the closest one ----------------
def num(s):
    s=s.replace(' ','').replace('−','-').replace('×10','e')
    for a,b in zip('⁰¹²³⁴⁵⁶⁷⁸⁹⁻','0123456789-'): s=s.replace(a,b)
    m=re.match(r'[+-]?[\d.]+(e-?\d+)?',s); return float(m[0]) if m else float('inf')
for p in P:
    if p['id'] in V:
        want=V[p['id']]; err=[abs(num(c)-want) for c in p['choices']]
        assert err[p['answer']]==min(err) and err[p['answer']]<=max(0.012*abs(want),1e-12),(p['id'],want,p['choices'])
NOTES={
 S:['Always convert to moles first; divide by the coefficient to find the limiting reactant.','Two isotopes: average mass = m₁x + m₂(1 − x). Solve for x.','Dilution: M₁V₁ = M₂V₂. Molarity is mol/L of solution; molality is mol/kg of solvent.','Empirical formula: percent → grams → moles → divide by the smallest → whole numbers.','Unknown element: use the product to find moles, then molar mass = mass/moles.','Make the final units match what the question asks for, with nothing left over.'],
 M:['Intermolecular forces: dispersion < dipole–dipole < hydrogen bonding (H on N, O or F). Stronger forces mean lower vapor pressure and higher boiling point.','Ideal gas: PV = nRT; density d = PM/RT. Dalton: P(A) = X(A)·P(total).','Effusion rate ∝ 1/√M. Average kinetic energy depends only on temperature.','Unit cells: corner 1/8, edge 1/4, face 1/2, center 1. SC Z = 1 (a = 2r), BCC Z = 2 (a = 4r/√3), FCC Z = 4 (a = 4r/√2).','Density from a unit cell: ρ = Z·M/(N_A·a³), with a in cm.','Phase diagrams: lines are two phases in equilibrium; the triple point has all three. At a phase transition ΔG = 0.','Colligative properties: ΔT = i·K·m.'],
 T:['ΔH°rxn = Σ ΔHf(products) − Σ ΔHf(reactants); elements in their standard states are zero.','Hess’s law: reverse a step → flip the sign; multiply a step → multiply ΔH.','Calorimetry: q = mcΔT; heat lost = heat gained. Constant volume (bomb) measures ΔE; constant pressure measures ΔH.','Bond enthalpies: ΔH ≈ broken − formed.','ΔG = ΔH − TΔS (match the units). ΔG° = −RT ln K. Spontaneous when ΔG < 0.','Entropy: gas > liquid > solid; more moles of gas means higher S.','Clausius–Clapeyron: ln(P₂/P₁) = −(ΔH/R)(1/T₂ − 1/T₁); the slope of ln P vs 1/T is −ΔH/R.'],
 K:['Orders come from experiment, or from the slow step of a mechanism, never from the overall equation.','Units of k: M^(1−n)·s⁻¹ for overall order n.','Integrated laws: zero order [A] = [A]₀ − kt; first ln[A] = ln[A]₀ − kt; second 1/[A] = 1/[A]₀ + kt.','Half-lives: zero [A]₀/2k; first ln 2/k (constant); second 1/(k[A]₀).','Arrhenius: k = A·e^(−Ea/RT); ln(k₂/k₁) = (Ea/R)(1/T₁ − 1/T₂). Only temperature and a catalyst change k.','Catalyst: consumed then regenerated. Intermediate: produced then consumed.'],
 E:['Write K from the balanced equation; leave out pure solids and liquids.','Le Châtelier: the system shifts to oppose a change. Pressure favors fewer moles of gas; heat is a product of an exothermic reaction; a catalyst shifts nothing.','Weak acid: [H⁺] ≈ √(Ka·C). Buffer: pH = pKa + log([A⁻]/[HA]); at half-neutralization pH = pKa.','Ksp with a common ion: the shared ion’s concentration is fixed by the other salt.'],
 O:['E°cell = E°cathode − E°anode; ΔG° = −nFE°; a positive E° is spontaneous.','VSEPR: count electron domains for the shape, then check whether bond dipoles cancel.','Isomers: build each carbon skeleton, then place the functional group on each distinct carbon.'],
}
